import{_ as l,o as i,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Performance Meeting 2021-12-09","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-12-09","date":"2021-12-09T00:00:00.000Z","updated":"2021-12-14T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","内存管理","PR 审查"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-12-09.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-12-09.md","lastUpdated":1780460162000}'),t={name:"posts/2021/Ceph_Performance_Meeting_2021-12-09.md"};function r(n,e,s,c,u,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Pull Requests (PRs) 更新</strong></p><ul><li>讨论了多个PR的进展情况，包括MD日志段优化、Gill处理优化、Alex大小设置、TTL缓存实现、Whip主平衡器、基于Huge Page的读缓冲区、BlueFS细粒度锁定、Bob fsck内存消耗优化、OSD PG移除优化等。</li><li>重点讨论了Bob fsck的内存使用问题，担心在特定情况下可能会有共享blob错误通过fsck过程。</li></ul></li><li><p><strong>Bob fsck内存使用问题</strong></p><ul><li>Adam提出对改进后的Bob fsck过程的担忧，担心某些情况下可能会有共享blob错误通过fsck过程。</li><li>Igor解释了改进后的Bob fsck不会提供错误检测，但在某些情况下可能会标记一些仍然良好的blob为潜在损坏。</li><li>讨论了在容器环境中运行OSD的内存限制问题，以及如何避免内存不足导致的崩溃。</li></ul></li><li><p><strong>TC Malloc线程缓存大小配置</strong></p><ul><li>Adam提议将TC Malloc线程缓存大小设置为可配置选项，而不是使用环境变量。</li><li>讨论了在perf glue代码中直接处理TC Malloc线程缓存大小的可能性，以及如何在全局配置中处理。</li></ul></li><li><p><strong>内存分配器讨论</strong></p><ul><li>讨论了不同内存分配器（如TC Malloc和Libsy Malloc）的内存碎片问题。</li><li>提到了Crimson中使用C-star分配器的情况，以及可能的改进方向。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要进一步讨论和测试Bob fsck的内存使用问题，特别是在容器环境中的应用。</li><li>确定将TC Malloc线程缓存大小设置为可配置选项，并考虑在perf glue代码中处理。</li><li>讨论了在Crimson中使用TC Malloc替代Libsy Malloc的可能性，特别是在BlueStore和AlienStore中。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续审查和测试相关PRs。</li><li>进一步讨论和优化Bob fsck的内存使用问题。</li><li>确定TC Malloc线程缓存大小的配置方式，并在perf glue代码中实现。</li><li>探索在Crimson中使用TC Malloc替代Libsy Malloc的可能性。</li></ul><h4 id="下次会议议题" tabindex="-1">下次会议议题 <a class="header-anchor" href="#下次会议议题" aria-label="Permalink to &quot;下次会议议题&quot;">​</a></h4><ul><li>讨论OSD同步写性能问题。</li><li>讨论更广泛的自性能优化话题。</li></ul><p><strong>会议结束时间</strong>: 会议持续了一个小时，所有议题均已讨论完毕。下次会议将继续讨论未尽事宜。</p><p>[原文中关键词保留，如Ceph, distributed storage, CRUSH algorithm, high availability, scalability, object storage, block storage, file system storage, consistency, decentralization, performance, bluestore, bluefs, rocksdb, OSD, MON, MDS, PG, RADOS, librados, libcephfs, cephfs, rbd, radosgw, RGW, RESTful API, authentication, authorization, encryption, erasure coding, replication, snapshots, clones, thin provisioning, iSCSI, Fibre Channel, NFS, CIFS, POSIX, monitoring, dashboard, management, orchestration, automation, integration, containerization, Kubernetes, Docker, virtualization, cloud computing, AWS, Azure, Google Cloud, hybrid cloud, multi-cloud, storage cluster, node, disk, SSD, HDD, JBOD, SAN, NAS, network, topology, failure domain, recovery, resilience, load balancing, caching, compression, deduplication, tiering, performance tuning, benchmarking, testing, validation]</p>',11)])])}const g=l(t,[["render",r]]);export{h as __pageData,g as default};
